import { describe, it, expect, vi } from "vitest";
import { Cart } from "../src/cart.ts";
import type { Product } from "../src/product.ts";
import type { DiscountPolicy } from "../src/pricing.ts";
import type { TaxCalculator } from "../src/tax.ts";
import type { ShippingCalculator } from "../src/shipping.ts";

const productA: Product = { id: "a", name: "Widget", unitPriceCents: 1000 };
const productB: Product = { id: "b", name: "Gadget", unitPriceCents: 2000 };

describe("Cart - line management", () => {
  it("add creates a new line", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    expect(cart.itemCount).toBe(2);
  });

  it("add merges quantity for same product", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    cart.add(productA, 3);
    expect(cart.itemCount).toBe(5);
  });

  it("add throws for non-positive quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 0)).toThrow(RangeError);
    expect(() => cart.add(productA, -1)).toThrow(RangeError);
  });

  it("add throws for non-integer quantity", () => {
    const cart = new Cart();
    expect(() => cart.add(productA, 1.5)).toThrow(RangeError);
  });

  it("add throws for negative unitPriceCents", () => {
    const cart = new Cart();
    const bad: Product = { id: "x", name: "Bad", unitPriceCents: -1 };
    expect(() => cart.add(bad, 1)).toThrow(RangeError);
  });

  it("remove deletes existing product", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(cart.remove("a")).toBe(true);
    expect(cart.itemCount).toBe(0);
  });

  it("remove returns false for unknown product", () => {
    const cart = new Cart();
    expect(cart.remove("unknown")).toBe(false);
  });

  it("updateQuantity changes line quantity", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 5);
    expect(cart.itemCount).toBe(5);
  });

  it("updateQuantity 0 removes the line", () => {
    const cart = new Cart();
    cart.add(productA, 3);
    cart.updateQuantity("a", 0);
    expect(cart.itemCount).toBe(0);
  });

  it("updateQuantity throws for unknown product", () => {
    const cart = new Cart();
    expect(() => cart.updateQuantity("unknown", 5)).toThrow();
  });

  it("updateQuantity throws for negative quantity", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    expect(() => cart.updateQuantity("a", -1)).toThrow(RangeError);
  });

  it("clear empties the cart", () => {
    const cart = new Cart();
    cart.add(productA, 1);
    cart.add(productB, 2);
    cart.clear();
    expect(cart.itemCount).toBe(0);
  });

  it("snapshot returns deep copy", () => {
    const cart = new Cart();
    cart.add(productA, 2);
    const snap = cart.snapshot();
    snap[0]!.quantity = 99;
    expect(cart.itemCount).toBe(2);
  });
});

describe("Cart - pricing pipeline", () => {
  it("subtotal is sum of (price * quantity)", () => {
    const cart = new Cart();
    cart.add(productA, 2); // 2000
    cart.add(productB, 1); // 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(4000);
  });

  it("empty cart returns all zeros", () => {
    const cart = new Cart();
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(0);
    expect(totals.discountCents).toBe(0);
    expect(totals.taxCents).toBe(0);
    expect(totals.shippingCents).toBe(0);
    expect(totals.totalCents).toBe(0);
  });

  it("discount is clamped to [0, subtotal]", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 99999, // way over subtotal
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    const totals = cart.totals();
    expect(totals.discountCents).toBe(1000); // capped at subtotal
  });

  it("negative discount is clamped to 0", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: () => -500,
    };
    const cart = new Cart({ discountPolicy: discount });
    cart.add(productA, 1);
    expect(cart.totals().discountCents).toBe(0);
  });

  it("tax is applied to discounted subtotal", () => {
    const discount: DiscountPolicy = {
      computeDiscountCents: (sub) => Math.floor(sub * 0.5), // 50% off
    };
    const tax: TaxCalculator = {
      computeTaxCents: (taxable) => Math.floor(taxable * 0.1), // 10% tax
    };
    const cart = new Cart({ discountPolicy: discount, taxCalculator: tax });
    cart.add(productA, 2); // subtotal 2000
    const totals = cart.totals();
    expect(totals.subtotalCents).toBe(2000);
    expect(totals.discountCents).toBe(1000);
    // tax on discounted (2000 - 1000 = 1000) → 100
    expect(totals.taxCents).toBe(100);
  });

  it("shipping receives discounted subtotal and lines", () => {
    const shipping: ShippingCalculator = {
      computeShippingCents: vi.fn().mockReturnValue(500),
    };
    const discount: DiscountPolicy = {
      computeDiscountCents: () => 200,
    };
